import{_ as a,o as l,c as r,a2 as e}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"使用手册","description":"AgoraIn v4 各角色日常操作速查","frontmatter":{"title":"使用手册","description":"AgoraIn v4 各角色日常操作速查"},"headers":[],"relativePath":"manual.md","filePath":"manual.md","lastUpdated":1791170742000}'),d={name:"manual.md"};function o(i,t,n,h,s,c){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="使用手册" tabindex="-1">使用手册 <a class="header-anchor" href="#使用手册" aria-label="Permalink to &quot;使用手册&quot;">​</a></h1><p>按角色速查：<strong>教师 / 班主任 · 教务与机构管理员 · 家长 · 平台运营方</strong>。</p><h2 id="教师" tabindex="-1">教师 <a class="header-anchor" href="#教师" aria-label="Permalink to &quot;教师&quot;">​</a></h2><h3 id="上课前" tabindex="-1">上课前 <a class="header-anchor" href="#上课前" aria-label="Permalink to &quot;上课前&quot;">​</a></h3><ol><li>打开一体机大屏（桌面端大屏模式），确认班级与签到码</li><li>需要签到时在后台「签到」创建签到码，学生扫码后名字实时上屏</li><li>需要点名时在「点名」选择场次模式（随机加权 / 顺序 / 指定）</li></ol><h3 id="下课后" tabindex="-1">下课后 <a class="header-anchor" href="#下课后" aria-label="Permalink to &quot;下课后&quot;">​</a></h3><ol><li>核对课时划消流水（自动扣减，异常可手工修正并填备注）</li><li>记录积分变动（打卡 / 点名 / 值日 / 答题卡自动入流水）</li><li>更新值日完成情况</li></ol><h3 id="考试与阅卷" tabindex="-1">考试与阅卷 <a class="header-anchor" href="#考试与阅卷" aria-label="Permalink to &quot;考试与阅卷&quot;">​</a></h3><ol><li>「试卷」新建或导入试卷 → 配置答题卡版面 → 打印（或批量生成一人一张）</li><li>学生作答后拍照上传（App 或网页端动态扫卡）</li><li>在「批改」页逐题复判：看识别内容、AI 建议分，快捷记分键改分</li><li>「确认出分」后成绩计入统计；需要时导出 CSV</li></ol><blockquote><p>快捷记分键按 0 → 满分间隔 0.5 分布；分差较大的答卷支持双判与仲裁。</p></blockquote><h2 id="班主任" tabindex="-1">班主任 <a class="header-anchor" href="#班主任" aria-label="Permalink to &quot;班主任&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>入口</th><th>说明</th></tr></thead><tbody><tr><td>通知发布</td><td>通知</td><td>支持定时发布，家长端带已读回执</td></tr><tr><td>值日轮换</td><td>值日</td><td>按周 / 按日轮换生成，可手工调整</td></tr><tr><td>座位编排</td><td>座位</td><td>拖拽调座；一键随机换座自动留存快照</td></tr><tr><td>家长绑定</td><td>学生</td><td>批量生成 6 位邀请码并导出 CSV 打印发放</td></tr><tr><td>留言处理</td><td>留言</td><td>家长留言集中处理，回复留痕</td></tr></tbody></table><h2 id="教务-机构管理员" tabindex="-1">教务 / 机构管理员 <a class="header-anchor" href="#教务-机构管理员" aria-label="Permalink to &quot;教务 / 机构管理员&quot;">​</a></h2><ol><li><strong>班级与学生</strong>：建班、批量导入学生、维护学号条码</li><li><strong>课程表</strong>：维护作息与班级课表，导入导出 ClassIsland 档案，一键推送到教室一体机</li><li><strong>设备</strong>：注册打卡设备与一体机，查看在线状态</li><li><strong>用户与权限</strong>：创建子账户（owner / teacher），按角色分配权限点</li><li><strong>成绩</strong>：按班级查看总分与得分率分析，导出 CSV 交教务归档</li><li><strong>AI 设置</strong>：配置 AI 地址与密钥（或使用平台额度）、提示词模板、图像外发开关、查看调用日志</li><li><strong>授权</strong>：查看区域授权状态与到期时间；主账号可签发子用户与邀请码</li></ol><h2 id="家长" tabindex="-1">家长 <a class="header-anchor" href="#家长" aria-label="Permalink to &quot;家长&quot;">​</a></h2><ol><li>用教师发放的 <strong>6 位邀请码</strong>绑定孩子（多孩可切换）</li><li>查看通知（带已读状态）、值日安排、班级资源</li><li>成绩概览需学校开启后可见（默认关闭，保护隐私）</li><li>可直接给老师留言，沟通留痕</li></ol><h2 id="平台运营方" tabindex="-1">平台运营方 <a class="header-anchor" href="#平台运营方" aria-label="Permalink to &quot;平台运营方&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>入口</th></tr></thead><tbody><tr><td>新建机构区域</td><td>「区域管理」创建区域</td></tr><tr><td>开通 / 续期机构</td><td>生成 <code>AGRR-</code> 激活码发给机构主账号</td></tr><tr><td>充值平台 AI</td><td>生成 <code>AGRT-</code> 额度码（金额 → 模型 token 折算）</td></tr><tr><td>查看区域用户</td><td>「区域管理」查看本区域用户并启停账号</td></tr><tr><td>远程存储</td><td>服务端配置 WebDAV 地址与密钥（平台级，所有机构数据统一上传）</td></tr></tbody></table><h2 id="教学之外-手写数据闭环-平台侧" tabindex="-1">教学之外：手写数据闭环（平台侧） <a class="header-anchor" href="#教学之外-手写数据闭环-平台侧" aria-label="Permalink to &quot;教学之外：手写数据闭环（平台侧）&quot;">​</a></h2><p>生成<strong>训练卡</strong> → 学生誊抄 → 扫回切行 / 切单字 → 本地 OCR 自动筛选可用样本 → 抽查纠正 → 导出训练集。用于持续微调自有手写识别模型，识别越用越准。</p><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/features.html">功能特性</a> · <a href="/guide.html">快速开始</a> · <a href="/faq.html">常见问题</a></li><li>旧版手册：<a href="/v3.2/manual.html">v3.2 使用手册</a></li></ul>',22)])])}const m=a(d,[["render",o]]);export{b as __pageData,m as default};
